21	import { formatStatusLabel, getStatusStyle } from "../../lib/status";
22	import type { TaskDetail } from "@/services/workflow-backend/types";
23	
24	export type TaskTabViewProps = {
25	  workspaceId: string;
26	  taskId: string;
27	};
28	
29	export function TaskTabView({ workspaceId, taskId }: TaskTabViewProps) {
30	  const { task, loading, error, reload } = useWorkspaceTask(
31	    workspaceId,
32	    taskId,
33	  );
34	
35	  if (loading) {
36	    return (
37	      <div
38	        data-task-tab-loading
39	        className="flex flex-1 items-center justify-center"
40	      >
41	        <p className="text-sm text-text-muted">Loading task…</p>
42	      </div>
43	    );
44	  }
45	
46	  if (error) {
47	    return (
48	      <div
49	        data-task-tab-error
50	        className="flex flex-1 flex-col items-center justify-center gap-4"
51	      >
52	        <AlertCircle className="h-8 w-8 text-danger" aria-hidden="true" />
53	        <p className="text-sm text-text-secondary">
54	          {error.message || "Failed to load task."}
55	        </p>
56	        {error.retryable && (
57	          <button
58	            type="button"
59	            onClick={reload}
60	            className="flex items-center gap-2 border border-border bg-surface px-3 py-1.5 text-xs font-medium text-text-primary transition-colors hover:bg-surface-subtle"
61	          >
62	            <RefreshCw className="h-3.5 w-3.5" aria-hidden="true" />
63	            Retry
64	          </button>
65	        )}
66	      </div>
67	    );
68	  }
69	
70	  if (!task) return null;
71	
72	  return <TaskTabContent task={task} onReload={reload} />;
73	}
74	
75	function TaskTabContent({
76	  task,
77	  onReload,
78	}: {
79	  task: TaskDetail;
80	  onReload: () => void;
81	}) {
82	  const { activeTaskTabId, closeTaskTab, goToBoard } = useWorkspaceContext();
83	  const [copied, setCopied] = useState(false);
84	  const statusColor = getStatusColor(task.status);
85	
86	  function handleBackToBoard() {
87	    if (activeTaskTabId) {
88	      closeTaskTab(activeTaskTabId);
89	      return;
90	    }
91	    goToBoard();
92	  }
93	
94	  function handleCopyId() {
95	    const textToCopy = task.task_name || task.id;
96	    if (navigator.clipboard) {
97	      navigator.clipboard.writeText(textToCopy).then(() => {
98	        setCopied(true);
99	        setTimeout(() => setCopied(false), 1500);
100	      });
101	    } else {
102	      const el = document.createElement("textarea");
103	      el.value = textToCopy;
104	      document.body.appendChild(el);
105	      el.select();
106	      document.execCommand("copy");
107	      document.body.removeChild(el);
108	      setCopied(true);
109	      setTimeout(() => setCopied(false), 1500);
110	    }
111	  }
112	
113	  return (
114	    <div
115	      data-task-tab-content
116	      className="flex h-full min-h-0 flex-col overflow-hidden bg-bg"
117	    >
118	      <header className="shrink-0 border-b border-border bg-surface px-6 py-4">
119	        <div className="flex items-center justify-between gap-3">
120	          <button
121	            type="button"
122	            data-back-to-board
