384	            <TaskActivityTimelineItem
385	              key={`${entry.occurred_at}-${entry.action}-${index}`}
386	              entry={entry}
387	              isLast={index === entries.length - 1}
388	            />
389	          ))}
390	        </ol>
391	      ) : (
