400	function getSortedTaskActivityEntries(
401	  activity: TaskDetail["activity"],
402	): TaskActivityTimelineEntry[] {
403	  if (!activity || activity.length === 0) return [];
404	
405	  return activity
406	    .map((entry, sequence) => {
407	      const entryTime = new Date(entry.occurred_at).getTime();
408	      return {
409	        ...entry,
410	        sequence,
411	        sortTime: Number.isNaN(entryTime)
412	          ? Number.NEGATIVE_INFINITY
413	          : entryTime,
414	      };
415	    })
416	    .sort((a, b) => {
417	      if (a.sortTime !== b.sortTime) return b.sortTime - a.sortTime;
418	      return a.sequence - b.sequence;
419	    });
420	}
